import {colorValueToHex} from './color-format'
import {colors} from './colors'

interface Oklab {
  l: number
  a: number
  b: number
}

interface PaletteSample {
  colorName: string
  step: string
  lab: Oklab
}

const HEX_PATTERN = /^#([0-9a-f]{6})$/i

const srgbChannelToLinear = (value: number) => {
  return value <= 0.04045 ? value / 12.92 : Math.pow((value + 0.055) / 1.055, 2.4)
}

const hexToRgb = (hex: string): {r: number; g: number; b: number} | null => {
  const match = hex.match(HEX_PATTERN)
  if (!match) return null

  const value = match[1]!

  const r = Number.parseInt(value.slice(0, 2), 16) / 255
  const g = Number.parseInt(value.slice(2, 4), 16) / 255
  const b = Number.parseInt(value.slice(4, 6), 16) / 255

  return {r, g, b}
}

const rgbToOklab = ({r, g, b}: {r: number; g: number; b: number}): Oklab => {
  const lr = srgbChannelToLinear(r)
  const lg = srgbChannelToLinear(g)
  const lb = srgbChannelToLinear(b)

  const l_ = Math.cbrt(0.4122214708 * lr + 0.5363325363 * lg + 0.0514459929 * lb)
  const m_ = Math.cbrt(0.2119034982 * lr + 0.6806995451 * lg + 0.1073969566 * lb)
  const s_ = Math.cbrt(0.0883024619 * lr + 0.2817188376 * lg + 0.6299787005 * lb)

  return {
    l: 0.2104542553 * l_ + 0.793617785 * m_ - 0.0040720468 * s_,
    a: 1.9779984951 * l_ - 2.428592205 * m_ + 0.4505937099 * s_,
    b: 0.0259040371 * l_ + 0.7827717662 * m_ - 0.808675766 * s_,
  }
}

const hexToOklab = (hex: string): Oklab | null => {
  const rgb = hexToRgb(hex)
  if (!rgb) return null
  return rgbToOklab(rgb)
}

const paletteSamples: PaletteSample[] = Object.entries(colors)
  .flatMap(([colorName, stops]) => {
    return Object.entries(stops).map(([step, cssValue]) => {
      const hex = colorValueToHex(cssValue)
      const lab = hex ? hexToOklab(hex) : null

      return lab ? {colorName, step, lab} : null
    })
  })
  .filter((sample): sample is PaletteSample => sample !== null)

const labDistance = (a: Oklab, b: Oklab) => {
  const dl = a.l - b.l
  const da = a.a - b.a
  const db = a.b - b.b
  return Math.sqrt(dl * dl + da * da + db * db)
}

const formatColorFamilyName = (colorName: string) => {
  if (!colorName) return 'color'
  return colorName.replace(/(^|\s|-)([a-z])/g, (_, prefix: string, char: string) => `${prefix}${char.toUpperCase()}`)
}

const findClosestPaletteSample = (lab: Oklab): PaletteSample | null => {
  let closest: PaletteSample | null = null
  let smallestDistance = Number.POSITIVE_INFINITY

  for (const sample of paletteSamples) {
    const distance = labDistance(lab, sample.lab)
    if (distance < smallestDistance) {
      smallestDistance = distance
      closest = sample
    }
  }

  return closest
}

const formatHexForAnnouncement = (hex: string) => hex.toUpperCase()

export const describeCustomColorValue = (value: string | null): string => {
  const hex = colorValueToHex(value)
  if (!hex) {
    return 'Custom color'
  }

  const lab = hexToOklab(hex)
  if (!lab) {
    return `Custom color (${formatHexForAnnouncement(hex)})`
  }

  const closest = findClosestPaletteSample(lab)
  if (!closest) {
    return `Custom color (${formatHexForAnnouncement(hex)})`
  }

  const friendlyName = formatColorFamilyName(closest.colorName)
  return `Custom ${friendlyName} (${formatHexForAnnouncement(hex)})`
}
