import {SearchIcon} from '@primer/octicons-react'
import {AnchoredOverlay, TextInput, Tooltip, VisuallyHidden} from '@primer/react'
import {Fragment, type Ref, useId, useMemo, useState} from 'react'

import {ReadOnlyKey, useReadOnly} from '../../hooks/use-read-only'
import styles from './ColorPickerItem.module.css'
import {describeCustomColorValue} from './utils/color-descriptions'
import {buildColorSwatchLabel} from './utils/color-format'
import {colors} from './utils/colors'

interface ColorPickerItemProps {
  label: string
  groupLabel: string
  value: string | null
  onChange: (color: {name: string; step: string; value: string}) => void
}

type PaletteMatch = {name: string; step: string; value: string} | null

const findPaletteMatch = (value: string | null): PaletteMatch => {
  if (!value) return null

  for (const [colorName, colorSteps] of Object.entries(colors)) {
    for (const [step, stepValue] of Object.entries(colorSteps)) {
      if (value === stepValue || value.endsWith(`-${colorName}-${step}`)) {
        return {name: colorName, step, value: stepValue}
      }
    }
  }

  return null
}

export function ColorPickerItem({label, groupLabel, value, onChange}: ColorPickerItemProps) {
  const readOnly = useReadOnly(ReadOnlyKey.THEME_PANEL)

  const [open, setOpen] = useState(false)
  const [searchTerm, setSearchTerm] = useState('')
  const swatchDescriptionPrefix = useId()

  const paletteMatch = useMemo(() => findPaletteMatch(value), [value])
  const activeValue = paletteMatch?.value ?? value

  const colorAnnouncement = useMemo(() => {
    if (paletteMatch) {
      return buildColorSwatchLabel(paletteMatch.name, paletteMatch.step)
    }

    if (activeValue) {
      return describeCustomColorValue(activeValue)
    }

    return 'No color selected'
  }, [activeValue, paletteMatch])

  const triggerLabelPrefix = useMemo(() => {
    const trimmedGroup = groupLabel.trim()
    const trimmedField = label.trim()
    if (!trimmedGroup) return trimmedField || 'Color picker'
    return `${trimmedGroup} ${trimmedField}`.trim()
  }, [groupLabel, label])

  const triggerAriaLabel = `${triggerLabelPrefix}: ${colorAnnouncement}`.trim()

  const filteredColors = useMemo(() => {
    if (!searchTerm) return colors

    const searchLower = searchTerm.toLowerCase()
    return Object.fromEntries(Object.entries(colors).filter(([name]) => name.toLowerCase().includes(searchLower)))
  }, [searchTerm])

  return (
    <AnchoredOverlay
      open={open}
      onOpen={() => setOpen(true)}
      onClose={() => {
        setOpen(false)
        setSearchTerm('')
      }}
      renderAnchor={anchorProps => {
        const {ref: anchorRef, ...restAnchorProps} = anchorProps as typeof anchorProps & {
          ref?: Ref<HTMLButtonElement>
        }

        const triggerButton = (
          <button
            {...restAnchorProps}
            ref={readOnly ? anchorRef : undefined}
            className={styles.trigger}
            disabled={readOnly}
            aria-label={triggerAriaLabel}
          >
            <span className={styles.triggerLabel} data-testid="color-picker-label">
              {label}
            </span>
            <span
              className={styles.triggerColor}
              style={{backgroundColor: activeValue ?? undefined}}
              data-empty={activeValue === null}
              aria-hidden="true"
            />
          </button>
        )

        if (readOnly) {
          return triggerButton
        }

        return (
          <Tooltip ref={anchorRef} text={triggerAriaLabel} direction="w">
            {triggerButton}
          </Tooltip>
        )
      }}
    >
      <div className={styles.pickerContainer}>
        <TextInput
          leadingVisual={SearchIcon}
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
          placeholder="Search colors..."
        />
        {Object.entries(filteredColors).map(([colorName, colorSteps]) => {
          return (
            <div key={colorName} className={styles.colorContainer}>
              <div className={styles.sectionHeading}>{colorName}</div>
              <div className={styles.colorList}>
                {Object.entries(colorSteps).map(([step, stepValue]) => {
                  const selected = value === stepValue || value?.endsWith(`-${colorName}-${step}`)
                  const ariaLabel = buildColorSwatchLabel(colorName, step)
                  const descriptionId = `${swatchDescriptionPrefix}-${colorName}-${step}-description`
                  return (
                    <Fragment key={`${colorName}-${step}`}>
                      <Tooltip text={`${ariaLabel}: ${stepValue}`} direction="n" delay="short">
                        <button
                          className={styles.colorItem}
                          onClick={() => {
                            onChange({name: colorName, step, value: stepValue})
                            setOpen(false)
                          }}
                          aria-label={ariaLabel}
                          aria-describedby={descriptionId}
                          data-selected={selected}
                          style={{
                            '--color': stepValue,
                          }}
                        />
                      </Tooltip>
                      <VisuallyHidden id={descriptionId}>{stepValue}</VisuallyHidden>
                    </Fragment>
                  )
                })}
              </div>
            </div>
          )
        })}
      </div>
    </AnchoredOverlay>
  )
}
